// Parse pages API response - block-based content (EditorJS format)
const firstItem = $input.first().json;

// Detect if response is wrapped in body
let response;
if (firstItem.body) {
  response = firstItem.body;
} else {
  response = firstItem;
}

let pages = [];
if (response.data && Array.isArray(response.data)) {
  pages = response.data;
} else if (Array.isArray(response)) {
  pages = response;
}

console.log(`Found ${pages.length} pages`);

// Helper: extract text from a block
function blockToText(block) {
  if (!block || !block.data) return '';

  const type = block.type;
  const data = block.data;

  // Heading
  if (type === 'heading') {
    const level = data.level || 2;
    const prefix = '#'.repeat(level);
    return `\n${prefix} ${data.text || ''}\n`;
  }

  // Paragraph
  if (type === 'paragraph') {
    const text = data.text || data.html || '';
    return cleanHtml(text) + '\n';
  }

  // HTML block
  if (type === 'html') {
    return cleanHtml(data.html || data.text || '') + '\n';
  }

  // List (ordered or unordered)
  if (type === 'list') {
    const items = data.items || [];
    if (!Array.isArray(items)) return '';
    return items.map(item => `- ${cleanHtml(String(item))}`).join('\n') + '\n';
  }

  // Table
  if (type === 'table') {
    const headers = data.headers || [];
    const rows = data.rows || [];
    let result = '';
    if (headers.length > 0) {
      result += headers.join(' | ') + '\n';
      result += headers.map(() => '---').join(' | ') + '\n';
    }
    rows.forEach(row => {
      if (Array.isArray(row)) {
        result += row.map(c => cleanHtml(String(c))).join(' | ') + '\n';
      }
    });
    return result;
  }

  // Image - just include alt and caption
  if (type === 'image') {
    return `[Imagine: ${data.alt || data.caption || 'image'}]\n`;
  }

  // Divider
  if (type === 'divider') {
    return '\n---\n';
  }

  // Fallback: try to get any text
  if (data.text) return cleanHtml(data.text) + '\n';
  if (data.html) return cleanHtml(data.html) + '\n';

  return '';
}

// Helper: clean HTML to plain text
function cleanHtml(html) {
  if (!html) return '';
  return String(html)
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .trim();
}

const results = [];

pages.forEach((page, idx) => {
  const title = page.title || page.slug || `Pagina ${idx + 1}`;
  const slug = page.slug || `page_${page.id || idx}`;

  // Extract content from blocks
  let content = '';

  if (Array.isArray(page.content)) {
    // Block-based content (new format)
    content = page.content.map(blockToText).filter(t => t.trim()).join('\n');
  } else if (typeof page.content === 'string') {
    // Old format - string content
    content = cleanHtml(page.content);
  }

  content = content.trim();

  if (content.length < 50) {
    console.log(`Skip page "${title}": only ${content.length} chars`);
    return;
  }

  // Build full document with title
  const fullText = `${title}\n\n${content}`;
  const fileName = `inginerie_${slug}.txt`.replace(/[^\w_.-]/g, '_');

  console.log(`Page "${title}": ${fullText.length} chars`);

  results.push({
    json: {
      text: fullText,
      metadata: {
        source_file: fileName,
        source_url: `https://inginerie.ulbsibiu.ro/dep.cie/`,
        file_type: 'web_page',
        page_title: title,
        page_slug: slug,
        ingested_at: new Date().toISOString(),
        char_count: fullText.length
      }
    }
  });
});

console.log(`Total pages to ingest: ${results.length}`);
return results;

// Parse news API response - 1 chunk per news item
const firstItem = $input.first().json;

// Detectează structura: cu sau fără body wrapper
let response;
if (firstItem.body) {
  // Răspuns wrapped din HTTP Request cu Include Response Headers
  response = firstItem.body;
} else {
  response = firstItem;
}

let newsItems = [];
if (response.data && Array.isArray(response.data)) {
  newsItems = response.data;
} else if (Array.isArray(response)) {
  newsItems = response;
}

console.log(`Found ${newsItems.length} news items`);

const results = [];

newsItems.forEach((item, idx) => {
  // Title poate fi în translations sau direct
  let title = item.title;
  let content = item.content || item.body || item.description || '';

  // Verifică translations (cum am văzut în imagine, content e acolo)
  if (item.translations && Array.isArray(item.translations) && item.translations.length > 0) {
    const ro = item.translations.find(t => t.locale === 'ro') || item.translations[0];
    if (ro) {
      title = ro.title || title;
      content = ro.content || ro.body || ro.description || content;
    }
  }

  // Fallback
  title = title || item.slug || `Anunț ${idx + 1}`;

  // Clean HTML
  content = String(content)
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

  if (content.length < 30) {
    console.log(`Skipping "${title}": content too short (${content.length} chars)`);
    return;
  }

  const date = item.published_at || item.created_at || '';
  const slug = item.slug || `news_${item.id || idx}`;
  const fileName = `inginerie_news_${slug}.txt`.replace(/[^\w_.-]/g, '_');

  const fullText = `${title}\n${date ? `Data: ${date}\n` : ''}\n${content}`;

  console.log(`News "${title}": ${fullText.length} chars`);

  results.push({
    json: {
      text: fullText,
      metadata: {
        source_file: fileName,
        source_url: `https://inginerie.ulbsibiu.ro/dep.cie/`,
        file_type: 'news',
        news_title: title,
        news_date: date,
        ingested_at: new Date().toISOString(),
        char_count: fullText.length
      }
    }
  });
});

return results;

