// Filter Junk Content — runs after Parse, before Loader
//
// Removes documents that are too short to be useful for RAG
// and cleans common scraping artifacts. Does NOT reject tables
// or pages with short structured lines (e.g., tutori, calendar).
// ════════════════════════════════════════════════════════

const items = $input.all();
const validItems = [];

const MIN_CONTENT_LENGTH = 80;  // lowered from 100 to keep short but useful pages

for (const item of items) {
  let content = item.json.content || item.json.text || item.json.body || '';

  if (typeof content !== 'string') {
    content = String(content);
  }

  // ── 1. Basic cleanup ──
  let cleaned = content
    .trim()
    .replace(/\r\n/g, '\n')              // normalize line endings
    .replace(/\n{3,}/g, '\n\n')          // collapse 3+ newlines to 2
    .replace(/[ \t]{2,}/g, ' ')          // collapse multiple spaces/tabs
    .replace(/^\s+|\s+$/gm, '')          // trim each line
    .replace(/(.)\1{15,}/g, '$1$1$1');   // collapse char repetitions (e.g., "------")

  // ── 2. Reject if too short after cleanup ──
  if (cleaned.length < MIN_CONTENT_LENGTH) {
    console.log(`Skipping short content (${cleaned.length} chars) from: ${item.json.source_url || item.json.url || item.json.title || 'unknown'}`);
    continue;
  }

  // ── 3. Pass through with cleaned content ──
  // NOTE: removed the "avgLineLength < 20" check that was rejecting
  // legitimate structured content (tables of tutors, schedules, etc.)
  validItems.push({
    json: {
      ...item.json,
      content: cleaned,
    },
  });
}

console.log(`Filter: ${items.length} in, ${validItems.length} out`);
return validItems;

